/**
 * Minimal self-hosted markdown renderer for CRM AI chat.
 * Handles: tables, headings, bold/italic, bullet lists, ordered lists, paragraphs.
 * No external dependencies. Safe HTML output (no script injection).
 */
(function (root) {
  'use strict';

  function esc(s) {
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function inline(text) {
    return esc(text)
      .replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>')
      .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*(.+?)\*/g, '<em>$1</em>')
      .replace(/`([^`]+)`/g, '<code class="text-xs bg-neutral-100 dark:bg-neutral-800 px-1 py-0.5 rounded font-mono">$1</code>');
  }

  function renderTable(block) {
    var lines = block.trim().split('\n').filter(function (l) { return l.trim(); });
    if (lines.length < 3) return '<p class="leading-relaxed">' + inline(block) + '</p>';

    var headers = lines[0].split('|').map(function (c) { return c.trim(); }).filter(Boolean);
    // lines[1] is the separator (---|---|---)
    var dataRows = lines.slice(2).filter(function (l) { return !/^[\s|:-]+$/.test(l); });

    var html = '<div class="overflow-x-auto my-2"><table class="min-w-full text-xs border-collapse">';
    html += '<thead class="bg-neutral-50 dark:bg-neutral-800/60"><tr>';
    headers.forEach(function (h) {
      html += '<th class="px-3 py-2 text-left font-semibold border-b border-neutral-200 dark:border-neutral-700 text-neutral-700 dark:text-neutral-300">' + inline(h) + '</th>';
    });
    html += '</tr></thead><tbody>';

    dataRows.forEach(function (row, i) {
      var cells = row.split('|').map(function (c) { return c.trim(); });
      // Strip leading/trailing empty cells from | ... |
      if (cells[0] === '') cells = cells.slice(1);
      if (cells[cells.length - 1] === '') cells = cells.slice(0, -1);
      html += '<tr class="' + (i % 2 === 0 ? '' : 'bg-neutral-50/50 dark:bg-neutral-800/30') + ' border-b border-neutral-100 dark:border-neutral-800">';
      cells.forEach(function (c) {
        html += '<td class="px-3 py-2 text-neutral-800 dark:text-neutral-200">' + inline(c) + '</td>';
      });
      html += '</tr>';
    });
    html += '</tbody></table></div>';
    return html;
  }

  function parse(md) {
    if (!md) return '';
    var out = '';
    // Normalise line endings and any HTML <br> tags the AI may emit
    var text = md.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
    text = text.replace(/<br\s*\/?>/gi, '\n');
    // Split into blocks separated by blank lines
    var blocks = text.split(/\n{2,}/);

    blocks.forEach(function (block) {
      block = block.trim();
      if (!block) return;

      // Table: contains | and a separator line
      if (block.indexOf('|') !== -1 && /\|\s*[-:]+\s*\|/.test(block)) {
        out += renderTable(block);
        return;
      }

      // Heading ## or ###
      var hMatch = block.match(/^(#{1,3})\s+(.+)/);
      if (hMatch) {
        var lvl = hMatch[1].length;
        var sizes = ['text-base font-bold mt-3', 'text-sm font-semibold mt-2', 'text-xs font-semibold mt-2'];
        out += '<p class="' + sizes[Math.min(lvl, 3) - 1] + ' text-neutral-900 dark:text-neutral-100">' + inline(hMatch[2]) + '</p>';
        return;
      }

      // Unordered list: lines starting with - or * or +
      if (/^[-*+]\s/.test(block)) {
        var items = block.split('\n').filter(function (l) { return /^[-*+]\s/.test(l.trim()); });
        out += '<ul class="list-disc list-inside space-y-1 my-1 text-neutral-800 dark:text-neutral-200">';
        items.forEach(function (item) {
          out += '<li>' + inline(item.replace(/^[-*+]\s+/, '')) + '</li>';
        });
        out += '</ul>';
        return;
      }

      // Ordered list: lines starting with 1. 2. etc.
      if (/^\d+\.\s/.test(block)) {
        var oitems = block.split('\n').filter(function (l) { return /^\d+\.\s/.test(l.trim()); });
        out += '<ol class="list-decimal list-inside space-y-1 my-1 text-neutral-800 dark:text-neutral-200">';
        oitems.forEach(function (item) {
          out += '<li>' + inline(item.replace(/^\d+\.\s+/, '')) + '</li>';
        });
        out += '</ol>';
        return;
      }

      // Default: paragraph — inline() first (so esc() runs on raw text), then swap \n→<br>
      out += '<p class="leading-relaxed text-neutral-800 dark:text-neutral-200">' + inline(block).replace(/\n/g, '<br>') + '</p>';
    });

    return out;
  }

  root.marked = { parse: parse };
}(window));
